/**
 * Westcoast Rippers — wave-dividers.js
 * Layered PNG waves (pirate-style background-position-x scroll).
 * PNGs are 1920x520 — use background-size: auto 100% so they scale
 * correctly at any container height without squashing.
 */
(function () {
  'use strict';

  var W1 = 'data:image/png;base64,';
  var W2 = 'data:image/png;base64,';
  var W3 = 'data:image/png;base64,';

  function injectStyles() {
    if (document.getElementById('kcak-wave-styles')) return;
    var style = document.createElement('style');
    style.id = 'kcak-wave-styles';
    style.textContent = '.kcak-ocean {  position: relative;  width: 100%;  height: 90px;  overflow: hidden;  line-height: 0;  margin-top: -2px;  margin-bottom: -2px;}.kcak-wave {  position: absolute;  left: 0;  width: 100%;  height: 100%;  background-repeat: repeat-x;  background-size: auto 100%;  will-change: background-position-x;}.kcak-wave--back {  bottom: 0;  animation: kcakWave1 9s linear infinite;  opacity: 0.5;}.kcak-wave--mid {  bottom: 0;  animation: kcakWave2 6s linear infinite;  opacity: 0.7;}.kcak-wave--front {  bottom: 0;  animation: kcakWave1 4s linear infinite;  opacity: 1;}@keyframes kcakWave1 {  from { background-position-x: 1920px; }  to   { background-position-x: 0; }}@keyframes kcakWave2 {  from { background-position-x: 0; }  to   { background-position-x: 1920px; }}';
    document.head.appendChild(style);
  }

  function initDivider(wrap) {
    var canvas = wrap.querySelector('canvas');
    var bgColor = canvas ? (canvas.dataset.to || '#040D1A') : '#040D1A';
    if (canvas) wrap.removeChild(canvas);

    var ocean = document.createElement('div');
    ocean.className = 'kcak-ocean';
    ocean.style.background = bgColor;

    var back = document.createElement('div');
    back.className = 'kcak-wave kcak-wave--back';
    back.style.backgroundImage = 'url(' + W3 + ')';

    var mid = document.createElement('div');
    mid.className = 'kcak-wave kcak-wave--mid';
    mid.style.backgroundImage = 'url(' + W2 + ')';

    var front = document.createElement('div');
    front.className = 'kcak-wave kcak-wave--front';
    front.style.backgroundImage = 'url(' + W1 + ')';

    ocean.appendChild(back);
    ocean.appendChild(mid);
    ocean.appendChild(front);
    wrap.appendChild(ocean);
  }

  function init() {
    injectStyles();
    document.querySelectorAll('.wave-divider-wrap').forEach(initDivider);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();

/* ── Hero parallax PNG injection ── */
(function () {
  'use strict';
  // Reuse the same base64 PNGs already decoded above by the browser.
  // We locate them from the already-created .kcak-wave--back/mid/front elements
  // so we don't re-embed. Instead pull from the first divider's layers.
  function applyHeroPNGs() {
    var back  = document.querySelector('.kcak-wave--back');
    var mid   = document.querySelector('.kcak-wave--mid');
    var front = document.querySelector('.kcak-wave--front');
    if (!back) return; // wave-dividers not yet initialised

    var imgBack  = back.style.backgroundImage;
    var imgMid   = mid.style.backgroundImage;
    var imgFront = front.style.backgroundImage;

    var pwBack  = document.querySelector('.pw-layer--back');
    var pwMid   = document.querySelector('.pw-layer--mid');
    var pwFront = document.querySelector('.pw-layer--front');

    if (pwBack)  pwBack.style.backgroundImage  = imgBack;   // waves-3, deep
    if (pwMid)   pwMid.style.backgroundImage   = imgMid;    // waves-2, mid
    if (pwFront) pwFront.style.backgroundImage = imgFront;  // waves-1, foam
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyHeroPNGs);
  } else {
    applyHeroPNGs();
  }
})();
